<?php $escape = static fn (mixed $value): string => htmlspecialchars((string) ($value ?? ''), ENT_QUOTES, 'UTF-8'); ?>
<section class="section">
    <header class="admin-header"><div><h1>Gestionar promociones</h1><p>Administra campañas, vigencia, imagen y contenido público.</p></div><?php if ($action === 'list'): ?><a href="<?php echo $baseUrl; ?>/admin/promociones/nueva" class="btn">Nueva promoción</a><?php else: ?><a href="<?php echo $baseUrl; ?>/admin/promociones" class="btn btn--secondary">Volver al listado</a><?php endif; ?></header>
    <?php if (!empty($notice['message'])): ?><p class="alert alert--success" data-auto-dismiss="5000"><?php echo $escape($notice['message']); ?></p><?php endif; ?><?php if (!empty($error)): ?><p class="alert alert--error"><?php echo $escape($error); ?></p><?php endif; ?>
    <?php if ($action === 'list'): ?>
        <?php if (!$promotions): ?><div class="card empty-state"><p>No hay promociones registradas.</p></div><?php else: ?><div class="table-wrapper"><table class="table"><thead><tr><th>ID</th><th>Imagen</th><th>Título</th><th>Estado</th><th>Vigencia</th><th>Acciones</th></tr></thead><tbody><?php foreach ($promotions as $item): ?><tr><td data-label="ID"><?php echo (int) $item->id; ?></td><td data-label="Imagen"><?php if ($item->imagePath): ?><img src="../<?php echo $escape($item->imagePath); ?>" alt="" width="50" height="50" style="object-fit:cover;border-radius:4px;"><?php else: ?><span class="ticket-muted">Sin imagen</span><?php endif; ?></td><td data-label="Título"><strong><?php echo $escape($item->title); ?></strong><div class="ticket-meta"><?php echo $escape($item->shortDescription); ?></div></td><td data-label="Estado"><span class="status status--<?php echo $item->active ? 'active' : 'inactive'; ?>"><i class="fas fa-<?php echo $item->active ? 'check-circle' : 'times-circle'; ?>"></i> <?php echo $item->active ? 'Activa' : 'Inactiva'; ?></span></td><td data-label="Vigencia"><?php echo $item->startDate ? $escape(date('d/m/Y', strtotime($item->startDate))) : 'Sin inicio'; ?> - <?php echo $item->endDate ? $escape(date('d/m/Y', strtotime($item->endDate))) : 'Sin fin'; ?></td><td data-label="Acciones" class="table__actions"><a href="<?php echo $baseUrl; ?>/admin/promociones/<?php echo $item->id; ?>/editar" class="table__action" aria-label="Editar promoción" title="Editar promoción"><i class="fas fa-edit" aria-hidden="true"></i><span class="table-action-label">Editar</span></a><form method="post" class="inline-form" onsubmit="return confirm('¿Seguro que deseas eliminar esta promoción?');"><input type="hidden" name="_csrf_token" value="<?php echo $csrf; ?>"><input type="hidden" name="form_action" value="delete"><input type="hidden" name="id" value="<?php echo $item->id; ?>"><button type="submit" class="table__action table__action--danger table__action-button" aria-label="Borrar promoción" title="Borrar promoción"><i class="fas fa-trash" aria-hidden="true"></i><span class="table-action-label">Eliminar</span></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
    <?php else: ?><div class="card panel-card"><form method="post" enctype="multipart/form-data" class="admin-form"><input type="hidden" name="_csrf_token" value="<?php echo $csrf; ?>"><input type="hidden" name="form_action" value="save"><input type="hidden" name="id" value="<?php echo (int) ($promotion?->id ?? 0); ?>"><div class="admin-form__group"><label class="admin-form__label" for="title">Título de la promoción</label><input id="title" name="title" class="admin-form__input" required value="<?php echo $escape($promotion?->title); ?>"></div><div class="admin-form__group"><label class="admin-form__label" for="short_description">Descripción corta</label><textarea id="short_description" name="short_description" class="admin-form__textarea" rows="3" required><?php echo $escape($promotion?->shortDescription); ?></textarea></div><div class="admin-form__group"><label class="admin-form__label" for="full_description">Descripción completa</label><textarea id="full_description" name="full_description" class="admin-form__textarea" rows="5" required><?php echo $escape($promotion?->fullDescription); ?></textarea></div><div class="admin-form__group"><label class="admin-form__label" for="terms_conditions">Términos y condiciones</label><textarea id="terms_conditions" name="terms_conditions" class="admin-form__textarea" rows="5" required><?php echo $escape($promotion?->termsConditions); ?></textarea></div><div class="admin-form__row"><div class="admin-form__group"><label class="admin-form__label" for="start_date">Fecha de inicio</label><input type="date" id="start_date" name="start_date" class="admin-form__input" required value="<?php echo $escape($promotion?->startDate); ?>"></div><div class="admin-form__group"><label class="admin-form__label" for="end_date">Fecha de fin</label><input type="date" id="end_date" name="end_date" class="admin-form__input" required value="<?php echo $escape($promotion?->endDate); ?>"></div></div><div class="admin-form__group"><label class="admin-form__label" for="image">Imagen promocional</label><input id="image" name="image" type="file" class="admin-form__input" accept="image/*"><input type="hidden" name="current_img" value="<?php echo $escape($promotion?->imagePath); ?>"><?php if ($promotion?->imagePath): ?><small class="admin-current-media">Actual: <img src="../<?php echo $escape($promotion->imagePath); ?>" alt="" height="30"></small><?php endif; ?></div><div class="admin-form__group admin-form__check"><input type="checkbox" name="active" id="active" <?php echo ($promotion?->active ?? true) ? 'checked' : ''; ?>><label for="active" class="admin-form__label">Promoción activa</label></div><button type="submit" class="btn">Guardar promoción</button></form></div><?php endif; ?>
</section>
